/* fluxDB AI 交互稿页面。只渲染模拟数据，不调用模型、数据库或 MCP。 */
(() => {
  'use strict';
  const U = () => window.FluxPrototype;
  const E = v => U().esc(v);
  const I = (name, extra = '') => `<span class="icon ${extra}" data-icon="${name}" aria-hidden="true"></span>`;
  const B = (label, action, attrs = '', cls = '') => `<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
  const tag = (label, color = '') => `<span class="tag ${color}">${label}</span>`;
  const head = (kicker, title, subtitle, actions = '') => `<div class="page-header"><div><div class="kicker">${kicker}</div><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="page-actions">${actions}</div></div>`;
  const switcher = (kind, id, enabled, disabled = false) => `<input type="checkbox" class="switch" role="switch" aria-label="${E(id)}启用状态" data-change="${kind}" data-id="${E(id)}" ${enabled ? 'checked' : ''} ${disabled ? 'disabled' : ''}>`;
  function workbench(s) {
    const target = U().connections.find(c => c.id === s.connectionId);
    const isRedis = target.kind === 'redis';
    const query = isRedis ? `<span class="sql-comment"># 示例缓存查看，不执行真实命令</span>\nSCAN 0 MATCH demo:order:* COUNT 100\nTYPE demo:order:1001\nTTL demo:order:1001` : `<span class="sql-comment">-- 净销售额 · 已确认排除退款 · 示例查询</span>\n<span class="sql-key">SELECT</span> channel,\n       <span class="sql-key">SUM</span>(amount - refund_amount) <span class="sql-key">AS</span> net_revenue\n<span class="sql-key">FROM</span> orders\n<span class="sql-key">WHERE</span> status = <span class="sql-string">'paid'</span>\n  <span class="sql-key">AND</span> paid_at &gt;= <span class="sql-string">'2026-09-28'</span>\n<span class="sql-key">GROUP BY</span> channel\n<span class="sql-key">ORDER BY</span> net_revenue <span class="sql-key">DESC</span>;`;
    const data = isRedis ? [['demo:order:1001','hash','3,600','6个字段'],['demo:order:1002','string','-1','412 bytes'],['demo:order:1003','hash','1,800','6个字段']] : [['1001','Web','paid','2026-09-28 09:31:08','1,280.00','0.00'],['1002','App','paid','2026-09-28 09:42:11','698.00','0.00'],['1003','Web','paid','2026-09-28 10:07:24','2,490.00','190.00'],['1004','Web','paid','2026-09-28 10:18:40','328.00','0.00'],['1005','App','paid','2026-09-28 11:03:18','1,599.00','0.00'],['1006','Web','paid','2026-09-28 11:37:20','780.00','0.00'],['1007','App','paid','2026-09-28 12:06:51','468.00','0.00'],['1008','Web','paid','2026-09-28 13:04:07','1,890.00','0.00']];
    const cols = isRedis ? ['Key','类型','TTL（秒）','摘要'] : ['id','channel','status','paid_at','amount','refund_amount'];
    return `<div class="workbench"><div class="work-tabs"><div class="work-tab">${I('file-code')} 查询 1</div><div class="work-tab inactive">${I('table-2')} orders</div></div><div class="work-toolbar">${B(I('play')+'运行示例','run-sql','','primary')}${B(I('square'),'work-stop','aria-label="停止示例查询"','icon-only')}<span class="header-divider"></span><select aria-label="当前连接" data-change="connection">${U().connections.map(c => `<option value="${c.id}" ${s.connectionId === c.id ? 'selected' : ''}>${E(c.label)} / ${E(c.database)}</option>`).join('')}</select><span class="muted soft-note">${I('circle-check')} Docker · 示例已连接</span><span class="grow"></span>${B(I('wand-sparkles')+'询问 AI','open-ai')}</div><div class="editor"><div class="line-numbers">1<br>2<br>3<br>4<br>5<br>6<br>7<br>8<br>9</div><pre>${query}</pre></div><div class="result-tabs"><span class="active">结果</span><span class="muted">消息</span><span class="grow"></span><span class="muted soft-note">模拟数据</span></div><div class="result-area table-wrap"><table><thead><tr><th>#</th>${cols.map(c => `<th>${c}</th>`).join('')}</tr></thead><tbody>${data.map((r,i) => `<tr><td>${i+1}</td>${r.map(v => `<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="result-footer">${I('circle-check')} 查询成功 · 0.42s <span>${data.length} 行示例结果</span><span class="grow"></span>${B(I('wand-sparkles')+'解释当前 SQL','suggest','data-text="解释当前 SQL，并检查是否存在性能问题。"','ghost')}${B(I('file-search')+'历史','goto','data-page="history"','ghost')}</div></div>`;
  }
  function models(s) {
    const filtered = s.models.filter(m => (m.name+m.provider+m.kind).toLowerCase().includes(s.filters.models.toLowerCase()));
    return `<div class="page">${head('设置 / AI','大模型','管理生成模型与决策模型。路由、凭据状态与 Agent 绑定各自独立。',B(I('plus')+'新建模型','edit-model','data-id="new"','primary'))}<div class="content-toolbar"><div class="search">${I('search')}<input id="model-filter" aria-label="搜索模型" data-filter="models" placeholder="搜索名称、Provider…" value="${E(s.filters.models)}"></div><span class="soft-note">${s.models.length} 个模型 · 密钥不回显</span></div><div class="box table-wrap"><table><thead><tr><th>模型</th><th>能力与上下文</th><th>计价（输入/输出）</th><th>凭据</th><th>启用</th><th></th></tr></thead><tbody>${filtered.map(m => `<tr><td><div class="inline">${I(m.kind==='decision'?'workflow':'bot')}<div><div class="cell-title">${E(m.name)}</div><div class="cell-note">${E(m.provider)} · ${E(m.modelId)}</div></div></div></td><td>${tag(m.kind==='decision'?'决策':'生成',m.kind==='decision'?'blue':'')}<div class="cell-note">${m.kind==='generation' ? (m.tier==='strong'?'高能力':'经济')+' · '+m.contextWindow.toLocaleString()+' ctx / '+m.maxOutput.toLocaleString()+' out' : 'Choice / Score · 内置 Jev'}</div></td><td><div class="cell-title money">$${m.priceInput} / $${m.priceOutput}</div><div class="cell-note">缓存读 $${m.priceCached} · 每百万 Token</div></td><td>${tag(m.keyConfigured?'已配置':'缺少凭据',m.keyConfigured?'green':'amber')}</td><td>${switcher('model-enabled',m.id,m.enabled)}</td><td class="actions">${B(m.testing?'测试中…':'测试连接','test-model',`data-id="${m.id}" ${m.testing?'disabled':''}`,'ghost')}${B(I('pencil'),'edit-model',`data-id="${m.id}" aria-label="编辑${E(m.name)}"`,'icon-only ghost')}</td></tr>`).join('')}</tbody></table></div><div class="section-title"><h2>默认模型与决策</h2></div><div class="box box-body"><div class="form-grid"><div class="field"><label for="default-model">默认主模型</label><select id="default-model" data-change="default-model">${s.models.filter(m=>m.kind==='generation').map(m=>`<option value="${m.id}" ${m.id===s.defaultModelId?'selected':''}>${E(m.name)}</option>`).join('')}</select><small>用户在会话中固定模型时，不被自动路由覆盖。</small></div><div class="field"><label for="decision-model">默认决策模型</label><select id="decision-model" data-change="default-decision"><option value="auto" ${s.decisionModelId==='auto'?'selected':''}>自动选择唯一合格模型</option>${s.models.filter(m=>m.kind==='decision').map(m=>`<option value="${m.id}" ${m.id===s.decisionModelId?'selected':''}>${E(m.name)}</option>`).join('')}</select><small>Jev 是内置可选能力，不配置也可运行主 Agent。</small></div></div><div class="notice" style="margin-top:18px">${I('key')}<div>界面稿只模拟 Keep / Set / Clear 和凭据状态，不处理真实密钥。请勿填写真实 API Key。</div></div></div></div>`;
  }
  const internalTools = () => [
    {id:'ui.current_context',description:'当前界面上下文与@引用',write:false,internal:true},
    {id:'file.read',description:'授权目录文件读取',write:false,internal:true},
    {id:'artifact.export',description:'宿主安全导出产物',write:true,internal:true}
  ];
  function agentEditor(s, a) {
    const tabs = ['基本','模型与提示词','工具与内置能力'];
    const input=(id,label,value,type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${E(value)}" ${extra}></div>`;
    const toolList=[...U().tools,...internalTools()];
    const tabbar=`<div class="tabs agent-tabs" role="tablist" aria-label="Agent配置分区">${tabs.map((title,i)=>`<button class="tab ${i===(s.agentTab||0)?'active':''}" role="tab" aria-selected="${i===(s.agentTab||0)}" data-action="agent-editor-tab" data-tab="${i}">${title}</button>`).join('')}</div>`;
    const basic=`<section data-agent-panel="0" ${(s.agentTab||0)===0?'':'hidden'}><div class="form-grid"><div class="field wide"><label for="agent-name">名称</label><input id="agent-name" value="${E(a.name)}"></div><div class="field wide"><label for="agent-description">职责描述</label><textarea id="agent-description" style="min-height:86px;font-family:inherit">${E(a.description)}</textarea><small>描述用于路由与用户识别，不是硬流程约束。</small></div><div class="field wide"><label>执行目标</label><div class="inline">${tag('自动跟随当前界面')}</div><small>SQL 编辑器、表数据、Redis Key 等当前标签内容会自动捕获；切换标签页不改变已启动任务的目标。</small></div><div class="field"><label>Agent状态</label><label class="inline"><input id="agent-enabled" type="checkbox" ${a.enabled?'checked':''}>启用 Agent</label><small>缺少可用主模型时可以保存，但不能运行。</small></div></div></section>`;
const model=`<section data-agent-panel="1" ${(s.agentTab||0)===1?'':'hidden'}><div class="form-grid"><div class="field"><label for="agent-model">默认生成模型</label><select id="agent-model">${s.models.filter(m=>m.kind==='generation').map(m=>`<option value="${m.id}" ${m.id===a.modelId?'selected':''}>${E(m.name)}</option>`).join('')}</select></div>${input('agent-max-tokens','最大输出 Token 提示',a.maxOutputTokens,'number','min="128" max="32768"')}${input('agent-temperature','Temperature 提示',a.temperature,'number','min="0" max="2" step="0.1"')}<div class="field wide"><label for="agent-system-prompt">提示词 · 直接输入</label><textarea id="agent-system-prompt" maxlength="16384" style="min-height:260px">${E(a.systemPrompt)}</textarea><small>保存在此 Agent 中，没有模板/多版本/发布。编辑只影响下一个 Turn；权限、预算与工具校验仍由内核保证。</small></div></div></section>`;
    const toolPanel=`<section data-agent-panel="2" ${(s.agentTab||0)===2?'':'hidden'}><p class="page-subtitle">勾选表示模型可发现这些工具；每次调用仍按目标、参数、审计和批准校验。</p><h3>标准工具</h3><div class="agent-option-grid">${toolList.map(t=>`<label class="agent-option"><input type="checkbox" data-agent-tool="${t.id}" ${(a.toolIds||[]).includes(t.id)?'checked':''}><span><strong class="mono">${t.id}${t.internal?' <span class="tag">内部</span>':''}</strong><small>${E(t.description)}</small></span></label>`).join('')}</div><h3 style="margin-top:18px">内置能力</h3><div class="agent-option-grid">${U().plugins.filter(p=>p.id!=='jev').map(p=>`<label class="agent-option"><input type="checkbox" data-agent-plugin="${p.id}" ${p.mandatory||(a.pluginIds||[]).includes(p.id)?'checked':''} ${p.mandatory?'disabled':''}><span><strong>${E(p.name)}</strong><small>${p.mandatory?'内核约束，不可关闭':'仅在已授权范围生效'}</small></span></label>`).join('')}</div><label class="inline" style="margin-top:15px"><input id="agent-report" type="checkbox" ${a.report?'checked':''}>允许生成 BI / 报表产物</label></section>`;
    const enabled=a.enabled;
    return `<div class="box agent-pane"><div class="agent-pane-head"><div class="inline"><div class="agent-symbol">${I(a.icon)}</div><div><h2>${E(a.name||'新 Agent')}</h2><p class="cell-note">${a.isNew?'未保存草稿':'已保存'} · rev ${a.revision||0}${a.enabled?' · 默认入口':''}</p></div></div><div class="inline">${tag(enabled?'已启用':'未启用',enabled?'green':'')}<label class="inline" title="启用此 Agent"><input id="agent-enabled" type="checkbox" ${enabled?'checked':''}><span class="sr-only">启用 Agent</span></label></div></div>${tabbar}<div class="agent-pane-body">${basic}${model}${toolPanel}</div><div class="agent-pane-foot"><span class="cell-note" id="agent-dirty">${a.isNew?'新建草稿 · 尚未保存':'未修改'}</span><span class="grow"></span>${B(I('copy-plus')+'复制','copy-agent',`data-id="${a.id}"`)}${B(I('save')+'保存 Agent','save-agent',`data-id="${a.id}"`,'primary')}</div></div>`;
  }
  function agents(s) {
    const a=U().agentDraft();
    return `<div class="page agent-page">${head('AI Agent / 管理','Agent','每个 Agent 直接配置提示词、模型角色与插件能力。修改只影响下一个 Turn，不影响正在运行的任务。',B('高级执行设置','open-budget','','ghost'))}<div class="agent-master"><aside class="box agent-list"><div class="box-head"><span class="muted">AGENTS · ${s.agents.length}</span>${B(I('plus')+'新建','new-agent','','ghost')}</div><div class="agent-list-items">${s.agents.map(x=>`<button class="agent-list-item ${a?.id===x.id?'active':''}" data-action="select-agent" data-id="${x.id}"><span class="agent-list-avatar">${I(x.icon)}</span><span class="grow"><strong>${E(x.name)}</strong><small>${E(x.description.slice(0,26))}</small></span>${tag(x.enabled?'已启用':'未启用',x.enabled?'green':'')}</button>`).join('')}${a?.isNew?`<button class="agent-list-item active"><span class="agent-list-avatar">${I('plus')}</span><span class="grow"><strong>新 Agent</strong><small>未保存草稿</small></span>${tag('草稿','blue')}</button>`:''}</div><div class="agent-list-note">${I('info')}<div>权限是交集：用户授予 ∩ Agent 配置 ∩ 插件声明 ∩ 本轮范围 ∩ 连接权限。插件只能收窄。</div></div></aside><div class="agent-detail">${a?agentEditor(s,a):`<div class="box agent-placeholder">${I('bot')}<h2>选择一个 Agent</h2><p>左侧选择 Agent 编辑提示词、模型、工具、权限与运行限制，或新建一个。</p></div>`}</div></div></div>`;
  }
  const settingTabs = page => `<div class="tabs" role="tablist" aria-label="工具与MCP">${[['tools','工具'],['mcp','本地 MCP'],['plugins','内置插件'],['audit','安全审计']].map(([id,label])=>`<button class="tab ${page===id?'active':''}" role="tab" aria-selected="${page===id}" data-action="goto" data-page="${id}">${label}</button>`).join('')}</div>`;
  function tools(s) {
    const list = U().tools.filter(t => (s.toolGroup==='all'||t.group===s.toolGroup)&&(t.name+t.description).toLowerCase().includes(s.filters.tools.toLowerCase()));
    return `<div class="page">${head('设置 / 工具与 MCP','工具与 MCP','内部 Agent 与本地 MCP 共用工具、授权和不可变执行回执。')}${settingTabs('tools')}<div class="content-toolbar"><div class="inline"><div class="search">${I('search')}<input id="tool-filter" aria-label="搜索工具" data-filter="tools" placeholder="搜索工具…" value="${E(s.filters.tools)}"></div><select class="button" aria-label="工具分类" data-change="tool-group"><option value="all">全部能力</option>${['SQL','Redis','公共'].map(g=>`<option ${s.toolGroup===g?'selected':''}>${g}</option>`).join('')}</select></div><span class="soft-note">13 个标准工具</span></div><div class="box table-wrap"><table><thead><tr><th>工具</th><th>职责</th><th>风险</th><th>启用</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td><div class="cell-title mono">${E(t.name)}</div><div class="cell-note">${t.group} · v1</div></td><td>${E(t.description)}</td><td>${tag(t.write?'修改 / 授权':'读取 / 有界',t.write?'amber':'green')}</td><td>${switcher('tool-enabled',t.id,s.toolEnabled[t.id]!==false)}</td><td class="actions">${B('定义','tool-detail',`data-id="${t.id}"`,'ghost')}</td></tr>`).join('')}</tbody></table></div><div class="notice" style="margin-top:16px">${I('info')}启用工具只是让它可被发现。每次调用仍重新检查目标、参数、连接权限、安全审计和审批范围。</div></div>`;
  }
  function plugins(s) {
    return `<div class="page">${head('设置 / 工具与 MCP','工具与 MCP','内置能力自动注册，无需安装包。可选优化不成为运行的前置依赖。')}${settingTabs('plugins')}<div class="content-toolbar"><h2>内置能力</h2><span class="soft-note">12 项 · 第三方仅预留接口</span></div><div class="box">${U().plugins.map(p=>`<div class="plugin-row"><div class="agent-symbol">${I(p.icon)}</div><div class="grow"><div class="plugin-title">${E(p.name)}</div><p>${E(p.description)}</p></div><div class="plugin-meta">${p.id==='jev'?tag(U().jevStatus(),U().jevAvailable()?'green':'amber'):p.mandatory?tag('内核约束','blue'):tag(s.pluginEnabled[p.id]?'已启用':'已关闭',s.pluginEnabled[p.id]?'green':'')}${switcher('plugin-enabled',p.id,s.pluginEnabled[p.id],p.mandatory)}</div></div>`).join('')}</div><div class="notice" style="margin-top:16px">${I('plug')}第三方插件安装、市场与沙箱当前不实现。未来通过相同的能力契约扩展，不直接访问数据库、密钥或界面控件。</div></div>`;
  }
  function mcp(s) {
    const m = s.mcp;
    return `<div class="page">${head('设置 / 工具与 MCP','工具与 MCP','fluxDB 提供本地 stdio MCP Server，供 Claude Code 等外部 Agent 调用。',B(I('folder-up')+'导出示例配置','export-mcp','','primary'))}${settingTabs('mcp')}<div class="box"><div class="box-head"><div class="inline">${I('plug')}<div><h2>fluxdb-local</h2><div class="cell-note">本地 Server · stdio · 不需要配置内部主模型或 Jev</div></div></div><div class="inline">${tag(m.enabled?(m.testing?'握手中…':'已启用（模拟）'):'已关闭',m.enabled?'green':'')}${switcher('mcp-enabled','server',m.enabled)}</div></div><div class="box-body"><div class="form-grid"><div class="field"><label for="write-mode">写入模式</label><select id="write-mode" data-change="mcp-write"><option value="disabled" ${m.writeMode==='disabled'?'selected':''}>默认只读 · 不暴露修改工具</option><option value="scoped" ${m.writeMode==='scoped'?'selected':''}>限定范围预授权</option></select><small>客户端允许调用工具，不等于 fluxDB 的写入授权。</small></div><div class="field"><label>对外工具</label><div class="inline" style="height:34px">${tag(m.writeMode==='disabled'?'11 个只读 / 控制工具':'13 个候选工具','blue')}${B('查看定义','goto','data-page="tools"','ghost')}</div><small>按资源类型与权限过滤；直接调用隐藏工具也会拒绝。</small></div></div></div></div><div class="section-title between"><h2>已配置连接的授权范围</h2><span class="soft-note">仅授权勾选的测试资源</span></div><div class="box table-wrap"><table><thead><tr><th>允许访问</th><th>连接 / 范围</th><th>读写边界</th></tr></thead><tbody>${U().connections.map(c=>`<tr><td><input type="checkbox" data-change="mcp-resource" data-id="${c.id}" aria-label="授权${c.label}" ${m.resources.includes(c.id)?'checked':''}></td><td><div class="inline"><img class="tree-db-icon" src="../../apps/fluxdb-desktop/assets/db/${c.kind==='postgres'?'postgres':c.kind}.svg" alt=""><div><div class="cell-title">${E(c.label)}</div><div class="cell-note">${E(c.database)} ${c.kind==='redis'?'· Key prefix demo:*':'· 仅示例对象'}</div></div></div></td><td>${tag(m.writeMode==='scoped'?'限定对象，执行仍审计':'只读','green')}</td></tr>`).join('')}</tbody></table></div><div class="section-title between"><h2>客户端验证与活动</h2>${B(m.testing?'测试中…':I('play')+'模拟客户端测试','test-mcp',m.testing?'disabled':'')}</div><div class="code-box"><pre>claude -p --mcp-config ./fluxdb-local.json \\\n  --strict-mcp-config --tools "" \\\n  --allowedTools mcp__fluxdb_local__fluxdb_query \\\n  --max-budget-usd 1 "使用授权测试库查询订单总额"</pre></div><div class="box table-wrap" style="margin-top:12px"><table><thead><tr><th>客户端 / 工具</th><th>目标</th><th>状态</th></tr></thead><tbody><tr><td><div class="cell-title">Claude Code · fluxdb_query</div><div class="cell-note">示例 request-mcp-001</div></td><td>Docker MySQL / demo_shop</td><td>${tag(m.lastTest?'通过（模拟）':'示例记录',m.lastTest?'green':'')}</td></tr></tbody></table></div></div>`;
  }
  function audit(s) {
    return `<div class="page">${head('设置 / 工具与 MCP','工具与 MCP','在最终参数修改之后、实际执行之前审计。Jev 与普通插件不能覆盖拒绝。')}${settingTabs('audit')}<div class="notice">${I('circle-check')}<div><strong>安全审计始终开启</strong><br>参数或目标变化将使旧审计与审批失效；审计无法执行或保存时，操作不会继续。</div></div><div class="content-toolbar" style="margin-top:23px"><h2>审计记录</h2><select class="button" aria-label="审计筛选" data-change="audit-filter"><option value="all">全部判断</option><option value="allow" ${s.auditFilter==='allow'?'selected':''}>允许</option><option value="approval" ${s.auditFilter==='approval'?'selected':''}>需审批</option><option value="deny" ${s.auditFilter==='deny'?'selected':''}>拒绝</option></select></div><div class="box table-wrap"><table><thead><tr><th>调用 / 来源</th><th>目标</th><th>判断</th><th>匹配规则</th><th></th></tr></thead><tbody>${U().audits.filter(a=>s.auditFilter==='all'||s.auditFilter===a.decision).map(a=>`<tr><td><div class="cell-title mono">${a.tool}</div><div class="cell-note">${a.origin} · ${a.id}</div></td><td>${a.target}</td><td>${tag(a.decision==='allow'?'允许':a.decision==='deny'?'拒绝':'需审批',a.decision==='allow'?'green':a.decision==='deny'?'red':'amber')}</td><td><div class="cell-note mono">${a.rule}</div></td><td>${B('详情','audit-detail',`data-id="${a.id}"`,'ghost')}</td></tr>`).join('')}</tbody></table></div></div>`;
  }
  function budget(s) {
    const enabled=!!s.budget.costLimitEnabled;
    return `<div class="advanced-budget"><p class="page-subtitle">普通使用无需调整。费用上限可选，执行与上下文保护有默认值。</p><div class="notice" style="margin:15px 0">${I('info')}费用预算管“花多少钱”；上下文预算管“模型能装多少内容”；执行保护管“最多跑多久、多少轮”。三者不是同一个数字。</div><div class="between" style="margin:18px 0"><h3>费用上限（可选）</h3><label class="inline">启用金额限制 <input id="cost-limit-enabled" type="checkbox" class="switch" role="switch" ${enabled?'checked':''}></label></div><div class="form-grid"><div class="field"><label for="session-budget">单会话上限（USD）</label><input id="session-budget" type="number" min="0.01" step="0.1" value="${s.budget.session}" ${enabled?'':'disabled'}><small>包括主模型、Jev、摘要和报告生成。</small></div><div class="field"><label for="day-budget">每日上限（USD）</label><input id="day-budget" type="number" min="0.01" step="1" value="${s.budget.day}" ${enabled?'':'disabled'}><small>价格未知时显示未知，不当作免费。</small></div><div class="field"><label for="iteration-budget">最大模型迭代次数</label><input id="iteration-budget" type="number" min="1" max="200" value="${s.budget.iterations}"><small>防止反复调用工具却没有进展。</small></div><div class="field"><label for="concurrency-budget">最大活动任务数</label><input id="concurrency-budget" type="number" min="1" max="8" value="${s.budget.concurrency}"><small>限制数据库与模型并发负载。</small></div></div><div class="notice" style="margin-top:18px">${I('circle-check')}权限与安全审计始终执行，不能通过提高预算绕过。未启用金额限制时不要求先配置价格，仍保留时间、轮次、并发和结果大小限制。</div></div>`;
  }
  function history(s) {
    return `<div class="page">${head('AI Agent / 会话','会话历史','普通打开恢复上次查看的会话，新建才开始新的草稿。关闭面板不删除、不停止任务。',B(I('plus')+'新建会话','new-chat','','primary'))}<div class="box table-wrap"><table><thead><tr><th>会话</th><th>Agent / 目标</th><th>状态</th><th></th></tr></thead><tbody>${s.sessions.map(c=>`<tr><td><div class="cell-title">${E(c.title)}</div><div class="cell-note">${c.id} · ${c.messages.length} 条用户消息</div></td><td><div>${E(U().agentById(c.agentId)?.name||'通用Agent')}</div><div class="cell-note">${E(U().connectionById(c.targetId)?.label||'未知目标')}</div></td><td>${tag(c.status==='running'?'执行中':c.status==='approval'?'等待批准':c.status==='interrupted'?'已中断':'已完成',c.status==='running'?'blue':c.status==='approval'?'amber':'green')}</td><td class="actions">${B('打开','select-session',`data-id="${c.id}"`)}${B(I('pencil'),'rename-session',`data-id="${c.id}" aria-label="重命名会话"`,'ghost icon-only')}</td></tr>`).join('')}</tbody></table></div></div>`;
  }
  function report(s) {
    return `<div class="report-document"><div class="inline" style="margin-bottom:16px">${tag('任务产物 · 示例','green')}${tag('renderer fluxdb.bi.report')}${tag('快照 · 不自动刷新')}</div>${U().reportCard(false)}<div class="report-sql" id="report-sql" hidden><h3>来源 SQL</h3><div class="code-box" style="margin-top:9px"><pre>SELECT DATE_FORMAT(paid_at, '%Y-%m') AS month,
       SUM(amount - refund_amount) AS net_revenue
FROM orders
WHERE status = ? AND paid_at &gt;= ? AND paid_at &lt; ?
GROUP BY month ORDER BY month;

参数：[paid, 2026-03-01, 2026-09-01]</pre></div></div><p class="report-disclaimer">交互稿中的图表、数据和结果引用均为模拟；报告弹框只读现有快照，打开不会重新查询数据库。</p></div>`;
  }
  window.FluxPrototypePages = {workbench,models,agents,tools,plugins,mcp,audit,budget,history,report,settingTabs};
})();
